"""Render the browser-agent landing page; evidence comes from published run reports."""
from pathlib import Path
import html
import json


def build(page, root):
    report_path = root / 'tools/browser-agent/runs.json'
    report = json.loads(report_path.read_text()) if report_path.exists() else {'runs': []}
    runs = report.get('runs', [])
    rows = ''.join('<tr><td>' + html.escape(str(r.get('title', r.get('id', 'Run')))) + '</td><td>' + html.escape(str(r.get('attempt_label', 'Recorded run'))) + '</td><td>' + html.escape(str(r.get('status', 'unverified'))) + '</td><td>' + (f"{r['elapsed_ms']/1000:.2f} s" if isinstance(r.get('elapsed_ms'), (int, float)) else '—') + '</td></tr>' for r in runs)
    body = '''<link rel="stylesheet" href="./replay.css">
<div class="ba-hero"><p class="eyebrow">JevStyle Browser Agent · Preview</p><h1>A goal. A browser.<br>One decision at a time.</h1><p class="lead">JevStyle scores each next action and page element. Choose JevStyle-only decisions or a local 4B model that reviews every step, then inspect what the browser actually did.</p><div class="actions"><a class="button" href="#replay">Explore recorded runs <span aria-hidden="true">↘</span></a><a class="button secondary" href="#run-locally">Run it yourself</a></div></div>
<section class="ba-replay" id="replay" aria-labelledby="replay-title"><div class="ba-section-head"><div><p class="eyebrow">Inspect the evidence</p><h2 id="replay-title">Follow every choice</h2></div><span class="ba-label">Recorded replay</span></div>
<p class="ba-note">These are saved runs, not a live connection to your browser. Playback pauses between decisions for inspection; reported timings are from the original run.</p>
<p id="coverage-note" class="ba-coverage"></p><div id="protocol-summary" class="ba-protocols" aria-label="Recorded evaluation modes"></div><p class="ba-note">These are successive development runs, with changes to prompts and stopping policies. The counts are observed outcomes, not a controlled comparison of model accuracy.</p><div class="ba-report"><p id="report-summary" role="status">Loading recorded runs…</p><label class="ba-import">Open your run report<input id="report-file" type="file" accept=".json,application/json"></label></div>
<div id="load-error" class="ba-error" role="alert" hidden></div>
<div class="ba-workspace"><aside class="ba-scenarios"><label for="run-select">Scenario</label><select id="run-select" disabled><option>Loading…</option></select><p id="run-goal">Choose a run to inspect its goal and decisions.</p><a id="run-fixture" class="ba-note" hidden target="_blank" rel="noopener">Open synthetic test page ↗</a><dl class="ba-metrics"><div><dt>Independent check</dt><dd id="run-status">—</dd></div><div><dt>Decision loop</dt><dd id="run-time">—</dd></div><div><dt>End to end</dt><dd id="run-wall">—</dd></div><div><dt>Decisions</dt><dd id="run-calls">—</dd></div></dl><p id="run-model" class="ba-note"></p><p id="run-helpers" class="ba-note"></p><p id="run-mode" class="ba-note"></p><p id="run-completion" class="ba-note"></p><ul id="run-checks" class="ba-checks"></ul><p id="run-error" class="ba-error" hidden></p></aside>
<div class="ba-stage"><div class="ba-track"><label for="trace-track">Replay track</label><select id="trace-track"><option value="actions">Executed actions</option><option value="decisions">Model decisions</option></select></div><div class="ba-stage-top"><span id="step-count">No step selected</span><span id="step-time">—</span></div><div class="ba-decision"><p class="eyebrow" id="step-kind">Executed action</p><div id="step-operation">—</div><p id="step-label">Run traces will appear here.</p><p id="step-value" hidden></p><div id="step-details" class="ba-detail"></div><p id="step-source" class="ba-note"></p></div><div class="ba-probability"><h3>JevStyle operation scores</h3><div id="operation-bars"></div></div><div class="ba-probability"><h3>JevStyle target scores</h3><div id="target-bars"></div></div><figure id="step-image" hidden><img alt="Page captured during this recorded run"><figcaption>Recorded browser frame</figcaption></figure><div class="ba-controls"><button id="play" disabled type="button">Play replay</button><button id="previous" disabled type="button" aria-label="Previous decision">←</button><input id="scrubber" type="range" min="0" max="0" value="0" aria-label="Recorded decision" disabled><button id="next" disabled type="button" aria-label="Next decision">→</button></div></div></div>
<details class="ba-evidence"><summary>Run records and measurement scope</summary><p id="report-date"></p><p id="report-measurement"></p><p>Completion is checked separately from the agent's DONE decision. Runs marked “Independent verifier” are stopped when deterministic task checks pass; the model need not choose DONE. A reviewed or hybrid result includes the generative model and must not be interpreted as JevStyle-only accuracy. A successful fixture run shows one controlled task; it does not establish reliability across arbitrary websites. Failed and blocked runs remain visible.</p><p>See the report's timing scope for setup and verification boundaries. These measurements are not a direct comparison with the upstream 7.1-second video.</p><div class="ba-table"><table><thead><tr><th>Scenario</th><th>Attempt</th><th>Result</th><th>Elapsed</th></tr></thead><tbody id="run-table-body">''' + rows + '''</tbody></table></div><p><a href="./runs.json" download>Download the published run report</a></p></details>
<noscript><p>The replay controls need JavaScript. The run table and downloadable report remain available.</p></noscript></section>
<section class="ba-how" aria-labelledby="how-title"><div><p class="eyebrow">How it works</p><h2 id="how-title">Small choices.<br>Visible actions.</h2></div><ol><li><b>Observe</b><p>Read visible controls and assign each supported element an index.</p></li><li><b>Decide</b><p>JevStyle scores the next operation and compatible targets in one request. The reviewed configuration asks a local 4B model to review every step. Conditional recovery is also available as a separate setting.</p></li><li><b>Act and check</b><p>Execute the selected action. A separate text model supplies field values when needed. Read the updated page before continuing.</p></li></ol></section>
<section class="ba-setup" id="run-locally" aria-labelledby="setup-title"><p class="eyebrow">Your machine, your browser</p><h2 id="setup-title">Run the agent yourself</h2><p>Use Python 3.12+, <a href="https://docs.astral.sh/uv/getting-started/installation/">uv</a>, and Chrome. The source includes the local inspector, scenario runner, and independent result checks. The tested text helper is <code>qwen3:4b-instruct-2507-q4_K_M</code> served by Ollama; LM Studio is optional.</p><div class="actions"><a class="button" href="./jevstyle-browser.zip" download>Download the local runner ↓</a><a class="button secondary" href="/guides/run-locally/">Set up a local JevStyle model</a></div><pre><code>unzip jevstyle-browser.zip
cd jevstyle-browser
uv sync
cp .env.example .env
# Start JevStyle separately: jev-style serve --release 2b
# Start Ollama and load qwen3:4b-instruct-2507-q4_K_M.
# Configure the two endpoints in .env, then:
uv run jev</code></pre><p>Open <code>http://127.0.0.1:8766</code> for the live local inspector. Credentials stay in your local configuration. With a hosted model, the page observations required for decisions are sent to that provider; with a local decision model, those decisions run on your machine. Text generation follows your configured text-helper provider.</p><details><summary>Configuration and reproducibility</summary><p>Review is off by default (<code>JEVSTYLE_FALLBACK=0</code>), which preserves the JevStyle-only baseline. The per-step review configuration uses all three values below. A threshold of 0.45 enables conditional recovery; it is a different configuration and is not the full-suite result shown for review of every step.</p><pre><code>JEVSTYLE_FALLBACK=1
JEVSTYLE_FALLBACK_THRESHOLD=1
JEVSTYLE_FALLBACK_FORMAT=json_schema</code></pre><p>With these values in <code>.env</code>, run <code>uv run --env-file .env python scripts/run_scenarios.py --output artifacts/reviewed-suite</code>. This is JevStyle scoring plus 4B review of every step, not JevStyle-only decision making. Reports record recovery calls separately; all probability bars still come from JevStyle, not the recovery model. The default configuration uses JevStyle at <code>http://127.0.0.1:8765</code> and Ollama at <code>http://127.0.0.1:11434/v1</code>. Set the endpoints to your running services. The README and <code>.env.example</code> document model settings and the input budget. The published test run used a separate loopback Ollama instance; it does not require port 11434 specifically. The verified release suite selects hotel, reading, catalog, form, guide, autocomplete, and Wikipedia. Google Flights is an additional unfinished scenario; the default full runner also attempts it. To reproduce the seven-scenario scope, pass <code>--scenario hotel --scenario reading --scenario catalog --scenario form --scenario guide --scenario autocomplete --scenario wikipedia</code>. Use <code>uv run python scripts/run_scenarios.py --help</code> for the scenario runner. Its exported <code>runs.json</code> can be opened with “Open your run report” above; that file is read locally in this page and is not uploaded.</p><p>This integration is adapted from <a href="https://github.com/browser-use/jev-ultrafast">Browser Use's Jev Ultrafast</a>, released under MIT. The download preserves its license. JevStyle is independently maintained and is not affiliated with TypeSafe or Browser Use.</p></details></section>
<script type="module" src="./replay.js"></script>'''
    capture_path = root / 'tools/browser-agent/media/hotel-capture.json'
    if capture_path.exists():
        capture = json.loads(capture_path.read_text())
        frames = capture['frames']
        captured_run = capture['runs'][0]
        options = ''.join('<option value="./media/' + html.escape(frame['path'], quote=True) + '"' + (' selected' if i == len(frames)-1 else '') + '>' + ('Initial page' if i == 0 else f'After action {i}') + f' · {frame["elapsed_ms"]/1000:.2f} s</option>' for i, frame in enumerate(frames))
        last_frame = './media/' + frames[-1]['path']
        gallery = '<section class="ba-proof" aria-labelledby="proof-title"><div class="ba-section-head"><div><p class="eyebrow">Actual browser snapshots</p><h2 id="proof-title">A hotel search, step by step</h2></div><span class="ba-label">Still frames</span></div><p class="ba-note">A separate verified run of the synthetic hotel fixture: ' + f'{captured_run["elapsed_ms"]/1000:.2f} s, {captured_run["decision_calls"]} JevStyle scoring calls and {captured_run["fallback_calls"]} local 4B reviews. ' + 'These are snapshots after individual actions, not continuous video. Its timing is separate from the suite below.</p><div class="ba-proof-control"><label for="proof-frame">Recorded frame</label><select id="proof-frame">' + options + '</select><a href="./media/hotel-capture.json" download>Capture report ↓</a></div><a id="proof-link" href="' + last_frame + '" target="_blank" rel="noopener"><img id="proof-image" src="' + last_frame + '" width="1120" height="780" alt="Actual browser snapshot of the synthetic hotel fixture; the verified Casa Flora result is open" loading="lazy"></a></section>'
        body = body.replace('<section class="ba-replay"', gallery + '<section class="ba-replay"', 1)
    excluded = report.get('coverage', {}).get('excluded_from_latest', [])
    flight_runs = sorted([r for r in runs if r.get('id') == 'flights'], key=lambda r: r.get('generated_at', ''))
    scope_note = ('Google Flights remains unverified. ' + ('The latest seven-scenario suite excludes it; ' if 'flights' in excluded else '') + 'its most recent recorded attempt did not pass. Failed flight attempts are retained in the report.') if flight_runs and flight_runs[-1]['status'] != 'passed' else ''
    body = body.replace('<p id="coverage-note" class="ba-coverage"></p>', '<p id="coverage-note" class="ba-coverage"' + (' hidden' if not scope_note else '') + '>' + html.escape(scope_note) + '</p>')
    cards = []
    for label in report.get('comparison_batches', []):
        batch = [r for r in runs if r.get('batch_id') == label]
        if not batch:
            continue
        passed = sum(r['status'] == 'passed' for r in batch)
        reviewed = any(r.get('all_decisions_reviewed') for r in batch) and all(not r.get('decision_calls') or r.get('all_decisions_reviewed') for r in batch)
        mode = 'JevStyle scoring + 4B review of every step' if reviewed else 'JevStyle + conditional local recovery' if any(r.get('hybrid') for r in batch) else 'JevStyle decisions · text helper for field values'
        cards.append('<div class="ba-protocol"><b>' + html.escape(label) + '</b><span>' + f'{passed} / {len(batch)} independently verified' + '</span><small>' + mode + '</small></div>')
    body = body.replace('<div id="protocol-summary" class="ba-protocols" aria-label="Recorded evaluation modes"></div>', '<div id="protocol-summary" class="ba-protocols" aria-label="Recorded evaluation modes">' + ''.join(cards) + '</div>')
    page('tools/browser-agent/index.html', 'en', 'JevStyle Browser Agent: recorded runs and local runner | JevStyle', 'Inspect real browser-agent decisions, independent outcome checks, and run timings. Download the JevStyle browser agent and replay your own run reports.', body, '/tools/browser-agent/')
